			data[i*avg_run_len+j]=i; 
	
	/*  copy contents of the first block to all other blocks (for testing only)*/
	for(j=1; j<num_blocks;j++)
		for(i=0; i<num_block_threads;i++)
			*(data + j*num_block_threads+i) = data[i];
}


